import { useState, useEffect } from "react";
import api from "../api";

export default function AddLevelWithTestCases() {
  const [level, setLevel] = useState({
    level_no: "",
    title: "",
    description: "",
    difficulty: "Easy",
    youtube_link: "",
  });

  const [testCases, setTestCases] = useState([
    { input_data: "", expected_output: "" },
  ]);

  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const resize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  const handleLevelChange = (e) =>
    setLevel({ ...level, [e.target.name]: e.target.value });

  const handleTestChange = (i, e) => {
    const updated = [...testCases];
    updated[i][e.target.name] = e.target.value;
    setTestCases(updated);
  };

  const addTestCase = () =>
    setTestCases([...testCases, { input_data: "", expected_output: "" }]);

  const removeTestCase = (i) =>
    setTestCases(testCases.filter((_, idx) => idx !== i));

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post("/admin/level", { ...level, testCases });
      alert("Level created successfully");

      setLevel({
        level_no: "",
        title: "",
        description: "",
        difficulty: "Easy",
      });
      setTestCases([{ input_data: "", expected_output: "" }]);
    } catch {
      alert("Error saving data");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={styles.page}>
      <h2 style={styles.pageTitle}>➕ Create New Level</h2>

      {/* ================= LEVEL INFO ================= */}
      <section style={styles.section}>
        <h3 style={styles.sectionTitle}>Level Information</h3>

        <div
          style={{
            ...styles.row,
            flexDirection: isMobile ? "column" : "row",
          }}
        >
          <div style={styles.field}>
            <label style={styles.label}>Level Number</label>
            <input
              type="number"
              name="level_no"
              value={level.level_no}
              onChange={handleLevelChange}
              required
              style={styles.input}
            />
          </div>

          <div style={styles.field}>
            <label style={styles.label}>Difficulty</label>
            <select
              name="difficulty"
              value={level.difficulty}
              onChange={handleLevelChange}
              style={styles.input}
            >
              <option>Easy</option>
              <option>Medium</option>
              <option>Hard</option>
            </select>
          </div>
        </div>

        <div style={styles.field}>
          <label style={styles.label}>Problem Title</label>
          <input
            name="title"
            value={level.title}
            onChange={handleLevelChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.field}>
          <label style={styles.label}>Problem Description</label>
          <textarea
            name="description"
            value={level.description}
            onChange={handleLevelChange}
            required
            style={styles.textarea}
          />
        </div>
      </section>

      {/* ================= TEST CASES ================= */}
      <section style={styles.section}>
        <h3 style={styles.sectionTitle}>Test Cases</h3>

        {testCases.map((tc, i) => (
          <div key={i} style={styles.testCase}>
            <div style={styles.field}>
              <label style={styles.label}>Input</label>
              <textarea
                name="input_data"
                value={tc.input_data}
                onChange={(e) => handleTestChange(i, e)}
                required
                style={styles.textarea}
              />
            </div>

            <div style={styles.field}>
              <label style={styles.label}>Expected Output</label>
              <textarea
                name="expected_output"
                value={tc.expected_output}
                onChange={(e) => handleTestChange(i, e)}
                required
                style={styles.textarea}
              />
            </div>

            {testCases.length > 1 && (
              <button
                type="button"
                onClick={() => removeTestCase(i)}
                style={styles.removeBtn}
              >
                ❌ Remove Test Case
              </button>
            )}
          </div>
        ))}

        <button
          type="button"
          onClick={addTestCase}
          style={styles.addBtn}
        >
          + Add Another Test Case
        </button>
      </section>

      {/* ================= SUBMIT ================= */}
      <button type="submit" style={styles.submitBtn}>
        🚀 Create Level
      </button>
    </form>
  );
}

/* ================= STYLES ================= */

const styles = {
  page: {
    background: "#0f172a",
    minHeight: "100vh",
    padding: 24,
    color: "white",
    maxWidth: 900,
  },
  pageTitle: {
    fontSize: 24,
    marginBottom: 20,
  },
  section: {
    background: "#020617",
    padding: 18,
    borderRadius: 12,
    marginBottom: 20,
    boxShadow: "0 10px 25px rgba(0,0,0,0.4)",
  },
  sectionTitle: {
    color: "#38bdf8",
    marginBottom: 16,
    fontSize: 18,
  },
  row: {
    display: "flex",
    gap: 16,
  },
  field: {
    display: "flex",
    flexDirection: "column",
    marginBottom: 14,
    flex: 1,
  },
  label: {
    fontSize: 13,
    marginBottom: 6,
    color: "#94a3b8",
  },
  input: {
    background: "#0f172a",
    border: "1px solid #1e293b",
    borderRadius: 8,
    padding: "10px 12px",
    color: "white",
  },
  textarea: {
    background: "#0f172a",
    border: "1px solid #1e293b",
    borderRadius: 8,
    padding: 12,
    color: "white",
    minHeight: 90,
  },
  testCase: {
    background: "#0f172a",
    border: "1px solid #1e293b",
    borderRadius: 10,
    padding: 14,
    marginBottom: 14,
  },
  addBtn: {
    background: "#38bdf8",
    border: "none",
    color: "#020617",
    padding: "8px 14px",
    borderRadius: 8,
    cursor: "pointer",
    fontWeight: 600,
  },
  removeBtn: {
    background: "#ef4444",
    border: "none",
    color: "white",
    padding: "6px 12px",
    borderRadius: 6,
    cursor: "pointer",
    marginTop: 6,
  },
  submitBtn: {
    width: "100%",
    background: "#22c55e",
    border: "none",
    padding: "12px",
    fontSize: 16,
    borderRadius: 12,
    fontWeight: 700,
    cursor: "pointer",
  },
};
